export function compose(...functions) {
  return (text) => functions.reduce((current, fn) => fn(current), text);
}
export function makeSuffix(suffix) { return (text) => text + suffix; }
function privateSuffix(suffix) { return (text) => text + suffix; }
const holder = { get value() { return privateSuffix("!"); } };
export function composePrivate(text) { return compose(privateSuffix("!"))(text); }
export function dynamicFunction() { return function (text) { return this.tag + text; }; }
export function asTyped(value) { return value; }
export function asDynamic(value) { return value; }
